def resolve(path, cwd, links):
    if links is None:
        links = {}

    # Start with cwd if path is relative
    if not path.startswith('/'):
        current = cwd
    else:
        current = '/'
        path = path[1:]

    # Split path into components, filtering empty ones
    components = [c for c in path.split('/') if c]

    link_count = 0

    def resolve_components(current, components):
        nonlocal link_count

        for component in components:
            if component == '.':
                continue
            elif component == '..':
                if current != '/':
                    current = current.rsplit('/', 1)[0]
                    if not current:
                        current = '/'
            else:
                # Append component
                if current == '/':
                    current = '/' + component
                else:
                    current = current + '/' + component

                # Check if this path is a symlink
                if current in links:
                    link_count += 1
                    if link_count > 8:
                        return None

                    target = links[current]

                    # Resolve the target
                    if target.startswith('/'):
                        # Absolute target
                        current = '/'
                        target = target[1:]
                    else:
                        # Relative target - relative to directory containing the link
                        if '/' in current:
                            current = current.rsplit('/', 1)[0]
                        else:
                            current = '/'

                    # Parse target components
                    target_components = [c for c in target.split('/') if c]
                    result = resolve_components(current, target_components)
                    if result is None:
                        return None
                    current = result

        return current

    result = resolve_components(current, components)

    if result is None:
        return None

    # Remove trailing slash, except for root
    if result != '/' and result.endswith('/'):
        result = result.rstrip('/')

    return result

